const m=(family,title,items,extra={})=>({version:1,family,title,style:'editorial',unit:'',items:structuredClone(items),...extra});
const pair=(a,b,ids=['a','b'],labels=['甲组','乙组'])=>[{id:ids[0],label:labels[0],value:a},{id:ids[1],label:labels[1],value:b}];
const states=[{id:'original',label:'原始文件'},{id:'draft',label:'修改副本'},{id:'checked',label:'核对结果'}];
const sequence=(title,labels)=>m('narrative',title,labels.map(([id,label])=>({id,label})));
const causal=(title,labels)=>{const s=sequence(title,labels);s.family='causal';s.edges=s.items.slice(1).map((v,i)=>({from:s.items[i].id,to:v.id}));return s;};
export const longFilms=[{id:'long-data',title:'比较变化之前，先找到参照',width:960,height:540,style:'editorial',brief:'自编数据教学示例，解释增量、基数、增长比例与构成占比。所有数字可复算，不引用真实统计。',shots:[
 {text:'比较变化之前，先找到参照。这里使用两组自编数据，甲组二十，乙组八十。它们没有单位，也不代表真实调查。接下来只改变输入，观察同一幅图怎样给出不同答案。请先记住各组的身份，位置变了，身份也应该保留。',scene:m('comparison','先记住原来的数量',pair(20,80))},
 {text:'现在，两组都增加十个。甲组从二十变成三十，乙组从八十变成九十。图中的长度和旁边的数值一起变化，始终使用同一把尺子。这样我们看到的差别来自数据，而不是绘图时偷偷换了比例。',scene:m('comparison','同样增加 10',pair(20,80).map(v=>({...v,to:v.value+10})))},
 {text:'如果问题只是增加了多少，答案完全相同。甲组增加十个，乙组也增加十个。这时比较的是增量，原来的数量暂时退到背景。先确定问的是什么，再选择对应的数据，才能避免一张图同时回答几个不同的问题。',scene:m('comparison','比较增加的数量',pair(10,10,['da','db'],['甲组增量','乙组增量']))},
 {text:'换一个问题，甲组相对原来增加了多少。我们把增加的十个，除以原来的二十个，得到零点五，也就是百分之五十。分母必须是变化前的数量。若把变化后的三十放进分母，算出的就是另一个关系。',scene:m('ratio','甲组：增加量 / 原数量',pair(10,20,['delta','base'],['增加量','原数量']))},
 {text:'再看乙组。增加的仍然是十个，但原来的数量是八十。十除以八十，得到零点一二五，也就是百分之十二点五。同样的增加量，放在更大的基数旁边，所占的比例更小。这不是增量消失了，而是参照改变了。',scene:m('ratio','乙组：增加量 / 原数量',pair(10,80,['delta','base'],['增加量','原数量']))},
 {text:'把两个增长比例放在一起，差别就清楚了。甲组是百分之五十，乙组是百分之十二点五。这里的两根条形都表示百分比，使用相同单位。不能让一根表示数量，另一根表示百分比，然后仅凭长度判断谁的变化更大。',scene:m('comparison','用相同单位比较',pair(50,12.5),{unit:'%'})},
 {text:'还有一种常见的问题，甲组占总量的多少。变化前，甲组二十，乙组八十，总量是一百。甲组占百分之二十。这里的分母从原来的甲组数量，换成了两组相加的总量。因此，占比和增长比例不能互相替代。',scene:m('proportion','变化前的构成',pair(20,80))},
 {text:'变化以后，甲组三十，乙组九十，总量变成一百二十。甲组在总量里占四分之一，也就是百分之二十五。总量和分子同时变化时，需要重新计算占比，不能把刚才的百分之五十直接加到原来的占比上。',scene:m('proportion','变化后的构成',pair(30,90))},
 {text:'到这里，可以把计算过程拆成三个问题。先找增加量，再选正确的参照，最后说明得到的比例回答什么。图中的连线表示计算依赖，不表示现实世界的因果。一个结果是否正确，要同时看数字、分母和问题是否对应。',scene:causal('先选参照，再解释结果',[['delta','增加量'],['reference','正确参照'],['ratio-result','比例结果']])},
 {text:'换一组数字检验这个方法。甲组四十二，乙组一百四十。我们不沿用上一组的答案，也不根据条形的颜色猜结论。颜色帮助追踪对象，数值才决定计算。只要输入改变，图形和文字就应该从同一份数据重新生成。',scene:m('comparison','第二组自编输入',pair(42,140,['c','d']))},
 {text:'现在，两组都增加七个。甲组变成四十九，乙组变成一百四十七。这一镜故意交换两组的位置，但甲组仍然保持甲组的颜色，乙组也一样。观看时应该能跟住同一组数据，而不是把换位误认为两组交换了身份。',scene:m('comparison','换位置，保留身份',pair(42,140,['c','d']).reverse().map(v=>({...v,to:v.value+7})))},
 {text:'计算甲组的增长比例，七除以四十二，得到六分之一。写成小数，大约是零点一六七。因为小数已经取舍，画面应该用近似号。不能一边省略后面的数字，一边用等号声称这是完全相等的结果。',scene:m('ratio','取舍后使用近似号',pair(7,42,['delta','base'],['增加量','原数量']))},
 {text:'计算乙组的增长比例，七除以一百四十，等于零点零五，也就是百分之五。相同的七个，仍然对应不同的相对变化。换了输入，方法没有改变。比较之前，先确认分母，再决定是否能够把两个结果放到同一张图里。',scene:m('ratio','乙组仍使用原来的基数',pair(7,140,['delta','base'],['增加量','原数量']))},
 {text:'再把几个容易混淆的概念摆开。原数量告诉我们起点，增加量记录实际变化，增长比例回答相对起点变化多少。它们之间有计算关系，却不能省掉任何一项后随意替换。必要的标签保留在对象旁边，整段解释由旁白承担。',scene:m('structure','起点、变化、相对结果',[{id:'base',label:'原数量'},{id:'delta',label:'增加量'},{id:'result',label:'增长比例'}])},
 {text:'在发布一段数据解释之前，最后检查三件事。图形是否来自同一组数值，比较对象是否使用相同尺度，取舍后的小数是否明确标注。这样做不是为了让画面更复杂，而是让观众看到的长度、读到的文字和听到的解释相互支持。',scene:sequence('发布前核对',[['data','核对输入'],['scale','统一尺度'],['approx','说明取舍']])},
 {text:'回到最初的问题。同样增加十个，为什么看起来变化不同？如果比较增加量，两组相同；如果比较相对变化，就需要除以各自原来的数量。以后遇到一张变化图，先找对象，再找起点，最后问清分母。这套方法也要保留它的适用边界。',scene:sequence('对象 → 起点 → 分母',[['identity','同一对象'],['origin','原来起点'],['denominator','正确分母']])},
]},{id:'long-workflow',title:'让一份讲解从草稿走到可核对的交付',width:720,height:960,style:'technical',brief:'使用自编操作说明和真实工作台截图，说明已有项目保全、声音定位、视觉编排、完整成片与可编辑交付；不含人物表演。',shots:[
 {text:'一段讲解从草稿到交付，会经过文字、声音、画面和检查。工作台的任务，是让这些内容保持联系。先从已经存在的一份项目开始，保留原始材料。新的尝试放进新的版本，这样每一次调整都知道从哪里来，也能回到先前的状态。',scene:m('narrative','从已有材料开始',states)},
 {text:'先写清这次希望解释的问题。观众是谁，看完应该理解什么，还需要哪些前提。画面展示的是本机工作台的真实界面，用来说明输入的位置。界面上的按钮不是生成的示意图，视频也不把截图当成已经执行了操作的证据。',scene:m('product','真实工作台入口',[{id:'style',label:'全片风格入口',image:'production-updated.jpg'},{id:'alignment',label:'配音定位入口',image:'alignment-ui.jpg'}])},
 {text:'下一步检查内容依据。哪些数字可以重新计算，哪些结论来自已经核对的资料，哪些只是为了说明方法的自编例子。把它们记录清楚，才能知道后面的图形应该表达什么。画面看起来合理，并不能替代来源与推理本身的核对。',scene:causal('依据决定表达',[['source','内容依据'],['model','明确模型'],['visual','画面表达']])},
 {text:'准备好完整语意段的台词，再关联已有录音。原音频保留在素材中，不因为调整字幕就重新配音。这个顺序很重要，声音有自己的停顿和真实长度。画面应该跟随已经存在的讲解，而不是先做一串动画，再让声音勉强塞进去。',scene:sequence('先有声音，再定画面',[['script','原台词'],['audio','已有录音'],['timing','真实时长']])},
 {text:'读取录音后，先检查识别文字。少读一个字、多识别一个字，或者把同音字写错，都不能直接当作完全匹配。候选有问题时，原声音仍然保留。准确的流程需要显示不确定的地方，而不是把缺失的字词平均分到某几个时间点上。',scene:m('structure','区分文字与时间',[{id:'script',label:'原台词'},{id:'recognized',label:'识别文字'},{id:'difference',label:'文字差异'}])},
 {text:'文字对应以后，再看字词的起止。识别起点说明模型认为何时开始说这个字，声波低下去只说明声音变弱，并不能独自证明字已经结束。弱音和背景噪声会影响判断，所以界面保留逐字试听和人工起止校准，让时间可以被检查。',scene:causal('从候选走向校准',[['candidate','定位候选'],['listen','逐字试听'],['calibration','起止校准']])},
 {text:'这段特意保留一个长停顿。先看原始文件。停下来以后，再看修改副本。字幕应该在没有说话时退出，下一句开始时再出现。检查的重点不是让字幕一直占着画面，而是让每个时间窗对应当下真实说出的内容。',pauseAfter:'先看原始文件。',pauseSeconds:1.6,scene:m('narrative','停顿也是时间信息',states)},
 {text:'时间校准后，同一份结果同时供字幕和动作使用。比如讲到原始文件时，短暂强调原件；讲到修改副本时，把注意力交给副本。强调来自对象和台词之间的对应，不能仅仅因为到了整秒，就让所有元素一起闪动或一起放大。',scene:m('narrative','让重点跟随解说',states)},
 {text:'接着选择全片的视觉方案。字体层级、线条、底色和对象颜色需要贯穿多个镜头。切到另一种画面结构时，原始文件仍然是原来的对象。颜色可以帮助记忆，但标签也要保留，让观众不必只靠颜色区分内容。',scene:m('structure','换结构，保留对象',states)},
 {text:'每次切镜，都说明前后是什么关系。继续同一状态时，下一镜应该承接上一镜的终点；换一个角度比较时，要保留共同参照；进入不同时间或新场景时，说明为什么变化。切镜本身不会让故事自动连贯，状态交接才是关键。',scene:sequence('三种交接要说清',[['continue','承接终态'],['compare','换角度比较'],['reset','新场景']])},
 {text:'静态图片也有自己的能力边界。真实截图可以完整展示，也可以围绕一个明确细节裁切或放大。只有一张平面图时，不把简单缩放称作内部结构的真实运动。所用效果应当帮助看清内容，并让观众知道它展示的到底是什么。',scene:m('product','素材能力决定镜头',[{id:'alignment',label:'配音定位入口',image:'alignment-ui.jpg'},{id:'style',label:'全片风格入口',image:'production-updated.jpg'}])},
 {text:'把所有镜头连起来之后，再检查完整有声样片。单镜正确，整片仍可能出现节奏重复、字幕迟到、声音被切断或者前后状态跳变。此时需要按照正常速度从头看到尾，记录具体时间。不能只看三张关键帧，就把长片标成检查完成。',scene:sequence('完整播放检查',[['picture','画面连续'],['captions','字幕同步'],['sound','声音衔接']])},
 {text:'自动检测负责找可以计算的问题。例如帧数和画幅是否正确，字幕有没有越界，原始声音是否被换掉，工程里是否漏了素材。它们提供可重复的依据。发音是否自然，节奏是否合适，表达是否让人理解，仍然需要真正观看与听辨。',scene:m('structure','分别保留检查依据',[{id:'technical',label:'技术检查'},{id:'watch',label:'连续看片'},{id:'hearing',label:'实际听审'}])},
 {text:'发现问题以后，把意见记在对应的镜头和时间点。调整一段字幕，只让受影响的时序检查过期；更换全片视觉方案，则重新检查相关画面。没有变化的声音继续保留。这样返修可以追踪原因，而不必每次都把全部材料重新生成。',scene:causal('从问题返回对应位置',[['note','问题时间码'],['edit','局部修改'],['review','重新核对']])},
 {text:'交付时，不只有一个播放文件。还要提供独立字幕、素材来源和可编辑工程。工程应当在独立入口重新渲染，才能说明它具备继续制作的条件。文件夹里有几个文件，并不自动代表这些文件能够组合出同一个完整结果。',scene:sequence('交付可继续制作的材料',[['video','完整视频'],['subtitles','独立字幕'],['project','可编辑工程']])},
 {text:'最后回看这条路径。原始文件提供来路，修改副本承载尝试，核对结果决定下一步。工作台把这些步骤连接起来，让以后每部影片都能复用相同的质量约束。它也保留还没有检查的部分，让我们知道哪些已经可靠，哪些仍需要继续完成。',scene:m('narrative','保留来路，核对结果',states)},
]}];
